-- Santa Cruz Conecta | Migração inicial — executar em um projeto Supabase dedicado.
-- Exposição pública apenas para leitura de estabelecimentos publicados.
create table if not exists public.places (
  id text primary key,
  name text not null,
  category text not null,
  description text not null default '',
  website_url text not null,
  link_type text not null default 'site' check (link_type in ('site', 'guia', 'canais')),
  featured boolean not null default false,
  subtitle text not null default '',
  address text not null default '',
  phone text not null default '',
  tags text[] not null default '{}',
  mark text not null default '',
  source_url text not null default '',
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists places_published_category_idx on public.places (category) where is_published = true;
alter table public.places enable row level security;
revoke all on table public.places from anon, authenticated;
grant select on table public.places to anon, authenticated;
drop policy if exists "public read published places" on public.places;
create policy "public read published places" on public.places
  for select to anon, authenticated using (is_published = true);
-- Nenhuma política de INSERT/UPDATE/DELETE: usuários públicos não podem modificar.
-- Mudanças editoriais são realizadas no painel de administração do Supabase.

on conflict (id) do nothing;
